import{_ as r,o as d,c as n,af as s}from"./chunks/framework.B28LkSoM.js";const b=JSON.parse('{"title":"2027事业单位备考·可兼报考试全景（商丘·计算机）","description":"商丘能考、且笔试内容与\\"职测+公基\\"重合的全部考试：科目重合度、时间线、公告发布网站、岗位表发布方式、商丘规模，以及该加哪几个。","frontmatter":{"title":"2027事业单位备考·可兼报考试全景（商丘·计算机）","published":"2026-10-06T00:00:00.000Z","tags":["事业单位","备考","学习路线","考公考编","河南"],"description":"商丘能考、且笔试内容与\\"职测+公基\\"重合的全部考试：科目重合度、时间线、公告发布网站、岗位表发布方式、商丘规模，以及该加哪几个。","date":"2026-10-06T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/回收站🗑️/2027事业单位备考可兼报考试全景.md","filePath":"posts/回收站🗑️/2027事业单位备考可兼报考试全景.md"}'),o={name:"posts/回收站🗑️/2027事业单位备考可兼报考试全景.md"};function a(g,t,e,h,l,i){return d(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1791244800000"},[...t[0]||(t[0]=[s(`<blockquote><p><strong>给谁看的</strong>：2027 届计算机科学与技术本科，目标商丘。主战场是河南省事业单位联考（职测+公基）。</p><p><strong>一句话结论</strong>：这些考试的笔试内容大面积共用，<strong>时间天然错开</strong>，所以不是&quot;分心&quot;，而是&quot;让同一套复习有多个出口&quot;。</p></blockquote><hr><h2 id="一、一张表看懂-重合度排序" tabindex="-1">一、一张表看懂：重合度排序 <a class="header-anchor" href="#一、一张表看懂-重合度排序" aria-label="Permalink to &quot;一、一张表看懂：重合度排序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>排序</th><th>考试</th><th>科目</th><th>与「职测+公基」重合度</th><th>商丘规模</th><th>该不该加</th></tr></thead><tbody><tr><td>—</td><td><strong>河南省事业单位联考</strong></td><td>职测 + 公基</td><td><strong>100%（基准）</strong></td><td>1730 人，计算机岗 115 人</td><td><strong>主战场</strong></td></tr><tr><td>1</td><td><strong>乡村振兴村级协理员</strong></td><td><strong>职测 + 公基</strong></td><td><strong>100%（科目完全相同）</strong></td><td><strong>800 人</strong>（无专业限制）</td><td><strong>必加</strong></td></tr><tr><td>2</td><td><strong>社区网格事务协理员</strong></td><td>公基</td><td>~70%</td><td>620 人</td><td><strong>必加</strong></td></tr><tr><td>3</td><td>河南省考</td><td>行测 + 申论</td><td>行测 ≈ 职测 87%</td><td>364 岗 565 人，计算机 37 岗 46 人</td><td><strong>建议加</strong></td></tr><tr><td>4</td><td>国考</td><td>行测 + 申论</td><td>同上</td><td>56 岗 94 人，计算机 15 岗 25 人</td><td>顺手报</td></tr><tr><td>5</td><td>军队文职</td><td>公共科目 + 专业科目</td><td>公共科目 ≈ 85%</td><td><strong>仅 1 岗 2 人</strong>（考数学1）</td><td>岗位太少，慎重</td></tr><tr><td>6</td><td>河南省三支一扶</td><td>公基</td><td>~65%</td><td>309 人（计科可报约 179 人）</td><td><strong>建议加</strong></td></tr><tr><td>7</td><td>商丘辅警</td><td>公基+法律+时政</td><td>~60%</td><td>862 人（2025 年 10 月批次）</td><td>保底</td></tr><tr><td>8</td><td>法院聘用制书记员</td><td>法律+公基+速录</td><td>最高</td><td>263 人</td><td><strong>毕业后才能报</strong></td></tr><tr><td>9</td><td>河南省烟草专卖局</td><td>综合基础知识</td><td>高</td><td>含商丘市局</td><td>建议投</td></tr><tr><td>10</td><td>河南选调生（普通类）</td><td>行测+案例+写作</td><td>高</td><td>本科 25 人</td><td>看条件</td></tr><tr><td>11</td><td>银行 / 农商行</td><td>EPI+金融</td><td>中高</td><td>建行含商丘，科技类岗</td><td>顺手投</td></tr><tr><td>12</td><td>中储粮 / 邮政 / 移动</td><td>行测类</td><td>中</td><td>有商丘岗</td><td>顺手投</td></tr></tbody></table><hr><h2 id="二、时间线-它们天然错开-不是同时考" tabindex="-1">二、时间线：它们天然错开，不是同时考 <a class="header-anchor" href="#二、时间线-它们天然错开-不是同时考" aria-label="Permalink to &quot;二、时间线：它们天然错开，不是同时考&quot;">​</a></h2><p>这是最关键的一点——<strong>你不需要在同一个时间段准备很多考试，它们是一个接一个来的</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2026.10 中旬      2027 国考报名          → 11 月底笔试</span></span>
<span class="line"><span>2026.10 底-11 初  军队文职公告          → 12 月中旬笔试     ← 就在这个月</span></span>
<span class="line"><span>2026.11-12        银行/农商行/中储粮秋招 → 12 月笔试</span></span>
<span class="line"><span>2027.01 初        河南省考公告          → 3 月中旬笔试</span></span>
<span class="line"><span>2027.01 初        河南选调生公告        → 3 月上旬笔试</span></span>
<span class="line"><span>2027.03-04        烟草专卖局公告        → 4-5 月笔试</span></span>
<span class="line"><span>2027.04 下旬      ★ 事业单位联考公告    → 5 月底笔试        ← 主战场</span></span>
<span class="line"><span>2027.05.31        两个协理员公告        → 6/27、6/28 笔试</span></span>
<span class="line"><span>2027.06 上        三支一扶报名          → 7 月中旬笔试</span></span>
<span class="line"><span>2027.09-10        招才引智（多数要硕士）</span></span></code></pre></div><p><strong>从 2026 年 11 月到 2027 年 7 月，平均每个月都有一场。<strong>而且越往后内容越重合——6 月那两个协理员考的卷子和 5 月底事业单位联考</strong>一模一样</strong>。</p><hr><h2 id="三、逐个说清楚" tabindex="-1">三、逐个说清楚 <a class="header-anchor" href="#三、逐个说清楚" aria-label="Permalink to &quot;三、逐个说清楚&quot;">​</a></h2><h3 id="_1-乡村振兴村级协理员-最优-plan-b" tabindex="-1">1. 乡村振兴村级协理员（最优 Plan B） <a class="header-anchor" href="#_1-乡村振兴村级协理员-最优-plan-b" aria-label="Permalink to &quot;1. 乡村振兴村级协理员（最优 Plan B）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td><strong>《职业能力测验》+《公共基础知识》，各 100 分</strong>——和事业单位联考综合类完全一致</td></tr><tr><td><strong>时间</strong>（2026 年实际）</td><td>公告 5/31 → 报名 6/3–6/9 → <strong>笔试 6/27</strong></td></tr><tr><td><strong>公告在哪发</strong></td><td>河南省人社厅 hrss.henan.gov.cn、省教育厅、省农业农村厅、省人事考试中心 hnrsks.com；<strong>商丘指定网站：商丘人事考试网 www.sqrsks.cn</strong></td></tr><tr><td><strong>岗位表</strong></td><td>公告附件（只有&quot;省辖市-县区-名额&quot;，无专业限制）</td></tr><tr><td><strong>商丘规模</strong></td><td><strong>800 人</strong>：永城 225、柘城 145、宁陵 128、民权 100、夏邑 86、睢阳 53、虞城 52、睢县 11</td></tr><tr><td><strong>性质</strong></td><td><strong>纳入乡镇事业单位编制统筹管理</strong>（带事业编），试用期 12 个月，<strong>乡镇最低服务期 5 年（在村不少于 2 年）</strong>，2 年后统筹定岗到乡镇事业单位</td></tr><tr><td><strong>要补什么</strong></td><td>**什么都不用补。**科目完全相同，你 5 月底考完直接接着考</td></tr></tbody></table><blockquote><p>这是重合度最高、名额最多、还带编制的备选。代价是 5 年服务期。</p></blockquote><h3 id="_2-社区网格事务协理员" tabindex="-1">2. 社区网格事务协理员 <a class="header-anchor" href="#_2-社区网格事务协理员" aria-label="Permalink to &quot;2. 社区网格事务协理员&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>仅《公共基础知识》一科，含客观题+主观题，<strong>无面试</strong>（按笔试 1:1 进资格复审）</td></tr><tr><td><strong>时间</strong>（2026 年实际）</td><td>公告 5/31 → 报名 6/4–6/10 → <strong>笔试 6/28</strong></td></tr><tr><td><strong>公告在哪发</strong></td><td>同村级协理员；商丘页在 www.sqrsks.cn</td></tr><tr><td><strong>商丘规模</strong></td><td><strong>620 人</strong>：梁园 140、永城 133、睢阳 98、柘城 64、民权 55、示范区 47、虞城 36、夏邑 25、睢县 13、宁陵 9</td></tr><tr><td><strong>性质</strong></td><td>与街道（乡镇）<strong>签劳动合同</strong>，不是事业编。试用期 6 个月，期满纳入社区工作者队伍管理</td></tr><tr><td><strong>要补什么</strong></td><td>少一门职测，公基完全复用</td></tr></tbody></table><blockquote><p>和村级协理员<strong>连考两天</strong>（6/27、6/28），报名期重叠，2026 年可以同时报。</p></blockquote><h3 id="_3-河南省考-公务员" tabindex="-1">3. 河南省考（公务员） <a class="header-anchor" href="#_3-河南省考-公务员" aria-label="Permalink to &quot;3. 河南省考（公务员）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>行测 + 申论。行测 120 题/120 分钟，含政治理论 15 题</td></tr><tr><td><strong>重合度</strong></td><td>行测与职测<strong>约 87% 同源</strong>（120 题里 105 题同类型），净增量是&quot;政治理论 15 题&quot;——而公基里的政治和时政正好覆盖</td></tr><tr><td><strong>唯一从零的科目</strong></td><td><strong>申论</strong>（150 分钟）。估算需额外 60–100 小时，约 1.5–2 个月、每天 1.5 小时</td></tr><tr><td><strong>时间</strong>（2026 年实际）</td><td>公告 1/5 → 报名 1/6–1/12 → <strong>笔试 3/14</strong>。2027 年预计 1 月上旬公告、3 月中旬笔试</td></tr><tr><td><strong>公告在哪发</strong></td><td><strong>河南省人事考试中心 www.hnrsks.com</strong> → &quot;公务员考试录用专栏 → 公告通知&quot;；商丘转发在商丘人事考试网</td></tr><tr><td><strong>岗位表</strong></td><td>公告正文<strong>附件 1，官方 .xlsx</strong> 下载（2026 年那份：hnrsks.com/sitesources/hnsrskszx/upload/202601/20260104161140859.xlsx）</td></tr><tr><td><strong>报名入口</strong></td><td>hnrsks.com 专栏 → 跳转河南政务服务网身份认证</td></tr><tr><td><strong>商丘规模</strong></td><td>364–368 岗 / 565–572 人；<strong>计算机类可报 37 岗 46 人</strong>（本科可报 33 岗 42 人）；另有 120 岗 168 人&quot;不限专业&quot;</td></tr><tr><td><strong>商丘进面线</strong></td><td>45–78 分（百分制），市中心岗位需 60–70 分</td></tr><tr><td><strong>条件</strong></td><td>18–38 周岁；商丘 368 个岗位<strong>工作经历要求全部为&quot;无要求&quot;</strong>；49 岗 67 人要求党员</td></tr></tbody></table><h3 id="_4-国考" tabindex="-1">4. 国考 <a class="header-anchor" href="#_4-国考" aria-label="Permalink to &quot;4. 国考&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>行测 + 申论（分 3 类卷）</td></tr><tr><td><strong>时间</strong></td><td><strong>预计 2026 年 10 月 14 日前后公告、10 月中下旬报名、11 月底笔试</strong>——<strong>就在这几天</strong></td></tr><tr><td><strong>公告在哪发</strong></td><td>国家公务员局 <strong>www.scs.gov.cn</strong>；考录专题网站（2026 年度是 bm.scs.gov.cn/kl2026，2027 年度换后缀）</td></tr><tr><td><strong>岗位表</strong></td><td>《招考简章》单个 <strong>.xls 文件</strong>，在专题网站&quot;相关下载&quot;，公告当天同步发布</td></tr><tr><td><strong>商丘规模</strong></td><td>56 岗 94 人；<strong>计算机类 15 岗 25 人</strong>。单位构成：税务系统 85 人 + 金融监管总局商丘分局及 4 个县支局 7 人 + 国家统计局河南调查总队 2 人</td></tr><tr><td><strong>注意</strong></td><td>商丘<strong>没有&quot;不限专业&quot;岗位</strong>，56 岗全部有专业要求；计算机岗竞争极端（梁园区税务局某岗 <strong>303:1</strong>）</td></tr><tr><td><strong>建议</strong></td><td><strong>可以顺手报名当实战模考</strong>，但别把商丘国考岗当主攻方向</td></tr></tbody></table><h3 id="_5-军队文职-你问的那个" tabindex="-1">5. 军队文职（你问的那个） <a class="header-anchor" href="#_5-军队文职-你问的那个" aria-label="Permalink to &quot;5. 军队文职（你问的那个）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>公共科目（120 分钟/100 分/全客观题）+ 专业科目（120 分钟/100 分），同日两场</td></tr><tr><td><strong>公共科目构成</strong></td><td><strong>第一部分 基本知识</strong>（马克思主义理论、人文与社会、国防和军队、时事政治）+ <strong>第二部分 岗位能力</strong>（言语、数量、判断、资料）</td></tr><tr><td><strong>重合度</strong></td><td>岗位能力 ≈ 职测（近全覆盖）；基本知识 ≈ 公基（政治、法律、人文、时政重合）。<strong>要额外补的是&quot;国防和军队知识&quot;</strong>（文职的重点得分区）</td></tr><tr><td><strong>专业科目</strong></td><td>计算机岗一般考 <strong>数学1</strong>（高等数学 + 线性代数 + 概率论与数理统计），全军 26 个专业科目里没有独立的&quot;计算机&quot;科目</td></tr><tr><td><strong>时间</strong></td><td>近三年公告：2023-10-20、2024-11-07、2025-11-02，<strong>笔试都在 12 月上中旬</strong>。<strong>2027 年招考预计 2026 年 10 月底—11 月初公告、12 月中旬笔试</strong>（截至 10/6 官方尚未发布）</td></tr><tr><td><strong>公告在哪发</strong></td><td><strong>军队人才网 <a href="http://81rc.81.cn" target="_blank" rel="noreferrer">http://81rc.81.cn</a></strong>（备用 www.81rc.mil.cn），同时&quot;中国军号&quot;APP、&quot;八一通&quot;APP</td></tr><tr><td><strong>岗位表怎么发</strong></td><td><strong>独立页面的 xlsx 附件</strong>，与公告同步（比公告晚几分钟），在&quot;××年军队文职人员公开招考工作全面展开&quot;新闻页给下载链接。2026 年那份是 2.3MB 的 xlsx</td></tr><tr><td><strong>商丘规模（重点）</strong></td><td>2024 年 14 岗 14 人、2025 年 6 岗 6 人、<strong>2026 年 5 岗 6 人</strong>。<strong>计算机类能报的</strong>：2024 年 4 个（人武部参谋，考<strong>管理学</strong>）、2025 年 1 个（武警助理工程师，考<strong>数学1</strong>）、2026 年 1 个岗 2 人（武警助理工程师，考<strong>数学1</strong>）</td></tr><tr><td><strong>现实</strong></td><td>2026 年商丘另外 3 个人武部岗位新增了&quot;<strong>具有 2 年以上服役经历</strong>&quot;的门槛，无服役经历报不了。<strong>商丘本地对计算机本科生实际上只剩武警那 1 个岗位（2 人）</strong></td></tr><tr><td><strong>建议</strong></td><td>内容确实重合，但<strong>商丘岗位太少</strong>。如果考，要把范围放宽到河南全省（2026 年河南共 549 岗 699 人）</td></tr></tbody></table><h3 id="_6-河南省三支一扶" tabindex="-1">6. 河南省三支一扶 <a class="header-anchor" href="#_6-河南省三支一扶" aria-label="Permalink to &quot;6. 河南省三支一扶&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>仅《公共基础知识》一科</td></tr><tr><td><strong>时间</strong>（2026 年实际）</td><td>公告 6/5 → 报名 6/8–6/11 → <strong>笔试 7/11</strong>（注：2026 年因全省性作弊案成绩作废，8/22 重考）</td></tr><tr><td><strong>公告在哪发</strong></td><td>河南省人社厅 hrss.henan.gov.cn（三支一扶专栏）；<strong>商丘：商丘人事考试网 www.sqrsks.cn</strong></td></tr><tr><td><strong>商丘规模</strong></td><td>309 人 / 183 岗。计科可报：专业栏写&quot;0809 计算机类&quot;的 3 岗 4 人 + <strong>&quot;不限专业&quot;100 岗 175 人</strong> ≈ <strong>104 岗 179 人可报</strong></td></tr><tr><td><strong>服务期满</strong></td><td>考核合格<strong>且自愿留任</strong>的，在编制限额内<strong>办理入编及聘用手续</strong>（不是无条件，要单位有空编）</td></tr><tr><td><strong>条件</strong></td><td>2024 年及以后毕业的全日制大专及以上（2027 年届预计&quot;2025 年及以后&quot;）</td></tr></tbody></table><h3 id="_7-商丘辅警" tabindex="-1">7. 商丘辅警 <a class="header-anchor" href="#_7-商丘辅警" aria-label="Permalink to &quot;7. 商丘辅警&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>公共基础知识、法律知识、时事政治，满分 100 分 + 体能测试</td></tr><tr><td><strong>时间</strong></td><td>2025 年那批：公告 10/17 → 报名 10/21–10/23 → 笔试 11/1。<strong>2026 年批次截至 10/6 未发布</strong></td></tr><tr><td><strong>公告在哪发</strong></td><td><strong>商丘人事考试网 www.sqrsks.cn</strong> + &quot;平安商丘&quot;微信公众号</td></tr><tr><td><strong>商丘规模</strong></td><td>2025 年 862 名（男 634、女 228），<strong>全部为看护辅警</strong></td></tr><tr><td><strong>条件</strong></td><td>18–35 岁；大专及以上；男 ≥170cm、女 ≥160cm</td></tr><tr><td><strong>性质</strong></td><td>与公安机关签劳动合同，<strong>期限 2 年</strong>，不具有人民警察身份，<strong>不能转录为警察</strong></td></tr></tbody></table><h3 id="_8-法院聘用制书记员-毕业后才能报" tabindex="-1">8. 法院聘用制书记员（毕业后才能报） <a class="header-anchor" href="#_8-法院聘用制书记员-毕业后才能报" aria-label="Permalink to &quot;8. 法院聘用制书记员（毕业后才能报）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td><strong>法律专业知识 + 公共基础知识</strong>（全客观题，100 分）+ <strong>技能考试（计算机文字速录、文档编辑、数据报表处理）</strong>——计算机专业有天然优势</td></tr><tr><td><strong>时间</strong>（2026 年）</td><td>公告 3/2 → 报名 3/2–3/8 → 笔试 3 月中下旬</td></tr><tr><td><strong>公告在哪发</strong></td><td>商丘市中级人民法院网站 hnsqzy.hncourt.gov.cn + <strong>商丘人事考试网 www.sqrsks.cn</strong> + &quot;商丘天平之声&quot;公众号</td></tr><tr><td><strong>商丘规模</strong></td><td><strong>263 人</strong>（全省 2562 人）</td></tr><tr><td><strong>关键限制</strong></td><td><strong>&quot;未毕业的全日制在校生&quot;不得报考</strong>——2027 年 3 月你还是在校生，<strong>这一批报不了，要等毕业后的批次</strong></td></tr><tr><td><strong>条件</strong></td><td>专科及以上，18–30 岁</td></tr></tbody></table><h3 id="_9-河南省烟草专卖局-公司" tabindex="-1">9. 河南省烟草专卖局（公司） <a class="header-anchor" href="#_9-河南省烟草专卖局-公司" aria-label="Permalink to &quot;9. 河南省烟草专卖局（公司）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>先线上量化测试，再笔试&quot;<strong>综合基础知识</strong>&quot;（政策理论水平、分析解决问题能力、基本素质潜能）——<strong>和公基+职测几乎同源</strong></td></tr><tr><td><strong>时间</strong>（2026 年）</td><td>公告 4/3 → 报名 4/4–4/11 → 笔试 4 月下旬</td></tr><tr><td><strong>公告在哪发</strong></td><td>国家烟草专卖局 www.tobacco.gov.cn（招聘信息栏）+ 河南省局 ha.tobacco.gov.cn</td></tr><tr><td><strong>商丘</strong></td><td>招聘单位含 18 个市级局（<strong>含商丘市烟草专卖局</strong>）及下属县级局；计算机类在历年可报岗位之列</td></tr><tr><td><strong>条件</strong></td><td>2025.8.1–2026.7.31 毕业（2027 批次顺延）；未落实工作</td></tr></tbody></table><h3 id="_10-河南选调生-普通类" tabindex="-1">10. 河南选调生（普通类） <a class="header-anchor" href="#_10-河南选调生-普通类" aria-label="Permalink to &quot;10. 河南选调生（普通类）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>1 张卷 100 分：<strong>案例分析 + 行政能力测试 + 材料写作</strong>；面试结构化</td></tr><tr><td><strong>时间</strong>（2026 届）</td><td>公告 1/4 → 报名 1/6–1/11 → <strong>笔试 3/7</strong></td></tr><tr><td><strong>报名平台</strong></td><td><strong>xds.jyt.henan.gov.cn</strong>（唯一官方平台）</td></tr><tr><td><strong>商丘</strong></td><td>普通类<strong>本科 25 人</strong> + 硕博 10 人</td></tr><tr><td><strong>报考条件（关键）</strong></td><td>应届本科可报，但必须满足以下<strong>四选一</strong>：<strong>中共党员（含预备）、班级以上学生干部连续 1 年以上、校级以上奖励、参军入伍经历</strong>；本科 ≤25 周岁；必修课无不及格；需学校党委/就业部门审核推荐</td></tr><tr><td><strong>性质</strong></td><td>录用走《公务员录用审批表》，<strong>本质是公务员</strong>，本科下乡镇、村任职 2 年</td></tr><tr><td><strong>注意</strong></td><td>定向选调面向清北等双一流 + 省内 8 所指定高校，<strong>郑州升达不在名单内，不能报定向</strong></td></tr></tbody></table><h3 id="_11-银行-农商行-正在报名-就在这几天" tabindex="-1">11. 银行 / 农商行（正在报名，就在这几天） <a class="header-anchor" href="#_11-银行-农商行-正在报名-就在这几天" aria-label="Permalink to &quot;11. 银行 / 农商行（正在报名，就在这几天）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>科目</strong></td><td>EPI（言语/数量/判断/资料，≈职测）+ 综合知识（经济金融/时政/公基碎片）+ 英语 + 性格测评；建行分&quot;综合类&quot;和&quot;信息技术类&quot;两套卷</td></tr><tr><td><strong>时间</strong></td><td><strong>建行河南省分行 2027 校招 800 人，报名截止 2026-10-08，笔试初定 10 月底</strong>；农行、工行、中行、交行、邮储同期</td></tr><tr><td><strong>公告在哪发</strong></td><td>各行校招官网：建行 job.ccb.com、农行 career.abchina.com.cn</td></tr><tr><td><strong>商丘</strong></td><td><strong>建行工作地点含商丘及所辖县市</strong>，岗位含&quot;<strong>科技类专项人才</strong>&quot;（重点招计算机、人工智能、软件工程）</td></tr><tr><td><strong>河南农商银行系统</strong></td><td>2026 校招 1736 人，市县机构<strong>本科可报、专业不限</strong>；报名 11 月、笔试 12 月</td></tr></tbody></table><h3 id="_12-其他可以顺手投的" tabindex="-1">12. 其他可以顺手投的 <a class="header-anchor" href="#_12-其他可以顺手投的" aria-label="Permalink to &quot;12. 其他可以顺手投的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>科目</th><th>时间</th><th>商丘</th></tr></thead><tbody><tr><td>中国邮政河南</td><td>网申→笔试（行测类）→面试</td><td>10 月公告、10 月底截止</td><td>18 个市分公司含商丘，专业含计算机类</td></tr><tr><td>中国移动/联通/电信河南</td><td>线上测评/笔试（行测类）</td><td>9 月起</td><td>商丘市县分公司有岗</td></tr><tr><td>中储粮河南</td><td>笔试+心理测评+面试</td><td>11 月底报名、12 月考试</td><td>河南 27 家直属企业（商丘待查）</td></tr><tr><td>铁路郑州局</td><td><strong>面试为主</strong>，基本无笔试</td><td>10–11 月公告</td><td>与备考无重合，价值低</td></tr><tr><td>招才引智（事业单位引进）</td><td>考核/笔试+面试</td><td>每年 9–10 月</td><td>民权、柘城、睢阳等县区，<strong>基本要求硕士</strong>，本科机会少</td></tr><tr><td>公益性岗位</td><td>无笔试</td><td>滚动</td><td><strong>要求&quot;就业困难人员&quot;认定，普通应届生一般不符合</strong></td></tr></tbody></table><hr><h2 id="四、公告发布渠道速查-你特别问的" tabindex="-1">四、公告发布渠道速查（你特别问的） <a class="header-anchor" href="#四、公告发布渠道速查-你特别问的" aria-label="Permalink to &quot;四、公告发布渠道速查（你特别问的）&quot;">​</a></h2><h3 id="必须收藏的-3-个" tabindex="-1">必须收藏的 3 个 <a class="header-anchor" href="#必须收藏的-3-个" aria-label="Permalink to &quot;必须收藏的 3 个&quot;">​</a></h3><table tabindex="0"><thead><tr><th>网站</th><th>网址</th><th>看什么</th></tr></thead><tbody><tr><td><strong>商丘人事考试网</strong></td><td><strong><a href="http://www.sqrsks.cn" target="_blank" rel="noreferrer">http://www.sqrsks.cn</a></strong></td><td><strong>商丘所有本地考试的核心站点</strong>：事业单位联考、协理员、三支一扶、辅警、书记员、社区工作者</td></tr><tr><td><strong>河南省人事考试中心</strong></td><td><strong><a href="http://www.hnrsks.com" target="_blank" rel="noreferrer">http://www.hnrsks.com</a></strong></td><td>报名入口、查分入口、省考公告、联考公告</td></tr><tr><td><strong>河南省人社厅</strong></td><td><strong><a href="https://hrss.henan.gov.cn" target="_blank" rel="noreferrer">https://hrss.henan.gov.cn</a></strong></td><td>省级公告原文（联考、三支一扶、协理员）</td></tr></tbody></table><h3 id="分考试的渠道" tabindex="-1">分考试的渠道 <a class="header-anchor" href="#分考试的渠道" aria-label="Permalink to &quot;分考试的渠道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>考试</th><th>公告在哪发</th><th>岗位表怎么发</th></tr></thead><tbody><tr><td>河南省事业单位联考</td><td>省人社厅 + <strong>商丘人事考试网</strong></td><td>公告<strong>附件 xlsx</strong></td></tr><tr><td>乡村振兴/社区网格协理员</td><td>省人社厅 + 教育厅 + 农业农村厅 + <strong>商丘人事考试网</strong></td><td>公告<strong>附件</strong></td></tr><tr><td>三支一扶</td><td>省人社厅（三支一扶专栏）+ <strong>商丘人事考试网</strong></td><td>公告<strong>附件 xlsx</strong></td></tr><tr><td>河南省考</td><td><strong>hnrsks.com</strong> 公务员专栏</td><td>公告<strong>附件 1，官方 .xlsx</strong></td></tr><tr><td>国考</td><td><strong>www.scs.gov.cn</strong> + 考录专题网站</td><td>《招考简章》<strong>.xls</strong>，专题网站&quot;相关下载&quot;</td></tr><tr><td>军队文职</td><td><strong>军队人才网 <a href="http://81rc.81.cn" target="_blank" rel="noreferrer">http://81rc.81.cn</a></strong> + 中国军号 APP</td><td><strong>独立页面的 xlsx 附件</strong>，与公告同步</td></tr><tr><td>河南选调生</td><td><strong>xds.jyt.henan.gov.cn</strong></td><td>公告附件</td></tr><tr><td>商丘辅警</td><td><strong>商丘人事考试网</strong> + &quot;平安商丘&quot;公众号</td><td>公告附件</td></tr><tr><td>法院书记员</td><td>商丘中院官网 + <strong>商丘人事考试网</strong></td><td>公告附件</td></tr><tr><td>河南省烟草专卖局</td><td>www.tobacco.gov.cn + ha.tobacco.gov.cn</td><td>公告附件《岗位明细表》</td></tr><tr><td>银行</td><td>各行校招官网</td><td>网申系统内</td></tr><tr><td>商丘市人社局</td><td>rsj.shangqiu.gov.cn（通知公告）</td><td>—</td></tr><tr><td>商丘市公安局</td><td>gaj.shangqiu.gov.cn（通知公告）</td><td>—</td></tr></tbody></table><p><strong>实操建议</strong>：每周固定花 10 分钟刷一遍上面那 3 个必收藏网站。公告出来都是几天内报名，错过就没了。</p><hr><h2 id="五、我的建议-加哪几个" tabindex="-1">五、我的建议：加哪几个 <a class="header-anchor" href="#五、我的建议-加哪几个" aria-label="Permalink to &quot;五、我的建议：加哪几个&quot;">​</a></h2><h3 id="必加-零边际成本" tabindex="-1">必加（零边际成本） <a class="header-anchor" href="#必加-零边际成本" aria-label="Permalink to &quot;必加（零边际成本）&quot;">​</a></h3><p>**乡村振兴村级协理员 + 社区网格事务协理员。**科目和事业单位联考完全一致（前者连职测都考），报名和笔试都在 5 月底联考之后（6 月下旬），<strong>你不需要额外准备一分钟</strong>。2026 年商丘两个加起来 <strong>1420 个名额</strong>，还都无专业限制。</p><h3 id="建议加-成本低-收益大" tabindex="-1">建议加（成本低，收益大） <a class="header-anchor" href="#建议加-成本低-收益大" aria-label="Permalink to &quot;建议加（成本低，收益大）&quot;">​</a></h3><p>**河南省考。**行测与职测 87% 同源，唯一要补的是申论（约 1.5–2 个月、每天 1.5 小时）。商丘计算机类可报 37 岗 46 人，另有 120 岗不限专业，选择面远大于国考，进面线 45–70 分。时间在 3 月中旬，正好在你事业单位备考的冲刺期之前。</p><p>**河南省三支一扶。**只考公基，你已经在学；商丘计科可报约 179 人；服务期满有条件的入编政策。7 月中旬笔试。</p><h3 id="顺手报-几乎不额外准备" tabindex="-1">顺手报（几乎不额外准备） <a class="header-anchor" href="#顺手报-几乎不额外准备" aria-label="Permalink to &quot;顺手报（几乎不额外准备）&quot;">​</a></h3><p><strong>国考</strong>（报名就在这几天）：当实战模考用，别把商丘岗当主攻。<strong>河南省烟草专卖局</strong>：笔试名目就是&quot;综合基础知识&quot;，和你学的东西同源。<strong>银行秋招</strong>：建行河南 10 月 8 日截止，含商丘、有科技类岗。</p><h3 id="慎重" tabindex="-1">慎重 <a class="header-anchor" href="#慎重" aria-label="Permalink to &quot;慎重&quot;">​</a></h3><p><strong>军队文职</strong>：内容确实和你的备考高度重合（公共科目 ≈ 公基+职测），但<strong>商丘计算机岗近三年只有 1 个岗 2 人</strong>（还考数学1），人武部岗位 2026 年起加了&quot;2 年以上服役经历&quot;门槛。要考就把范围放宽到河南全省。</p><p><strong>法院书记员</strong>：重合度最高，但 2027 年 3 月你还是在校生，报不了——记下来，等毕业后的批次。</p><h3 id="别考虑" tabindex="-1">别考虑 <a class="header-anchor" href="#别考虑" aria-label="Permalink to &quot;别考虑&quot;">​</a></h3><p>国网河南（非电工类只要研究生）、铁路郑州局（面试为主无笔试）、公益性岗位（要&quot;就业困难人员&quot;认定）。</p><hr><h2 id="六、一张图记住优先级" tabindex="-1">六、一张图记住优先级 <a class="header-anchor" href="#六、一张图记住优先级" aria-label="Permalink to &quot;六、一张图记住优先级&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主战场  事业单位联考（5 月底）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 零成本接续  村级协理员（6/27）+ 网格协理员（6/28）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 低成本加    河南省考（3 月，补申论）+ 三支一扶（7 月，只考公基）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 顺手报      国考（11 月）+ 烟草（4 月）+ 银行（10 月）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ 慎重        军队文职（岗位太少）</span></span></code></pre></div><p><strong>核心判断</strong>：真正需要&quot;额外学新东西&quot;的只有<strong>申论</strong>一门。其他全部共用你已经准备好的职测和公基。所以你不是在分散精力，是在给同一份努力多开几个出口。</p>`,62)])])}const p=r(o,[["render",a]]);export{b as __pageData,p as default};
